import{_ as o}from"./chunks/autorizovanakonverze.1FBt7_hK.js";import{_ as t,o as n,c as i,j as e,a as r,aa as s}from"./chunks/framework.BAs_AphD.js";const p="/buildary-help-preview/media/cs/diary/autorizovanakonverze2.png",l="/buildary-help-preview/media/cs/diary/zamceno_scanem.png",b=JSON.parse('{"title":"Bez elektronického podpisu","description":"","frontmatter":{"title":"Bez elektronického podpisu","wiki":"cs:diary:signingwithout"},"headers":[],"relativePath":"diary/signingwithout.md","filePath":"diary/signingwithout.md","lastUpdated":1794209661000}'),d={name:"diary/signingwithout.md"};function u(k,a,c,z,h,m){return n(),i("div",null,[...a[0]||(a[0]=[e("h1",{id:"bez-elektronickeho-podpisu",tabindex:"-1"},[r("Bez elektronického podpisu "),e("a",{class:"header-anchor",href:"#bez-elektronickeho-podpisu","aria-label":'Permalink to "Bez elektronického podpisu"'},"​")],-1),e("p",null,"Když oprávněná osoba nemá elektronický podpis, podepíše záznam na papíře a do Buildary nahraje jeho sken. Nahráním skenu se záznam uzamkne stejně jako podpisem.",-1),e("div",{class:"video"},[e("iframe",{src:"https://www.youtube-nocookie.com/embed/0bqdjnFiVDU",title:"Video: Podepisování bez elektronického certifikátu",loading:"lazy",allowfullscreen:"",allow:"accelerometer; encrypted-media; gyroscope; picture-in-picture"})],-1),s('<h2 id="podepsat-dalsi-zaznam-na-papire" tabindex="-1">Podepsat Další záznam na papíře <a class="header-anchor" href="#podepsat-dalsi-zaznam-na-papire" aria-label="Permalink to &quot;Podepsat Další záznam na papíře&quot;">​</a></h2><ol><li>Připravte záznam na papíře: <ul><li>buď ho napište v Buildary jako Další záznam, stáhněte jeho PDF a vytiskněte,</li><li>nebo ho napište ručně. Tlačítkem <strong>PDF šablona</strong> v sekci Další záznamy si vytisknete prázdný list s hlavičkou, aby měl záznam stejnou podobu jako výstupy z Buildary.</li></ul></li><li>Záznam vlastnoručně podepište, a pokud je potřeba, připojte autorizační razítko ČKAIT.</li><li>Papír převeďte do PDF – prostým skenem, nebo autorizovanou konverzí (viz níže).</li><li>U záznamu otevřete <strong>Další volby</strong> a zvolte <strong>Nahrát scan tohoto zápisu</strong>. Vyberte PDF.</li></ol><div class="gallery"><figure class="shot"><img src="'+p+'" alt="Další volby u Dalšího záznamu s vyznačenou volbou Nahrát scan tohoto zápisu" loading="lazy"></figure><figure class="shot"><img src="'+l+'" alt="Další záznam se zeleným označením Zamknutý scanem" loading="lazy"></figure></div><p>Záznam se uzamkne a označí jako <strong>Zamknutý scanem</strong>. Nahraný soubor se automaticky stane přílohou Denního protokolu.</p><h2 id="prosty-scan-nebo-autorizovana-konverze" tabindex="-1">Prostý sken, nebo autorizovaná konverze <a class="header-anchor" href="#prosty-scan-nebo-autorizovana-konverze" aria-label="Permalink to &quot;Prostý sken, nebo autorizovaná konverze {#prosty-scan-nebo-autorizovana-konverze}&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Prostý sken</th><th>Autorizovaná konverze</th></tr></thead><tbody><tr><td>Jak vznikne</td><td>naskenujete podepsaný papír</td><td>papír převede pracoviště Czech POINT nebo notář</td></tr><tr><td>Právní váha PDF</td><td>jen kopie</td><td>stejná jako papírový originál – soubor obsahuje ověřovací doložku</td></tr><tr><td>Papírový originál</td><td><strong>musíte uchovat</strong> a do deníku uvést, kde je uložený</td><td>už ho nepotřebujete</td></tr></tbody></table><figure class="shot" style="--w:600px;"><img src="'+o+'" alt="Doložka o autorizované konverzi dokumentu na konci PDF" loading="lazy"><figcaption>Doložka autorizované konverze</figcaption></figure><div class="info custom-block"><p class="custom-block-title">Kdy je autorizovaná konverze nutná</p><p>Rozhodnutí je na vás a závisí hlavně na tom, jak důležitý je obsah záznamu. Technicky lze nahrát jakékoli PDF, tedy i běžný sken s podpisem.</p></div><h2 id="cely-denik-na-papire" tabindex="-1">Celý deník na papíře <a class="header-anchor" href="#cely-denik-na-papire" aria-label="Permalink to &quot;Celý deník na papíře&quot;">​</a></h2><p>Buildary můžete používat i tak, že Denní protokoly vytisknete a podepíšete na papíře. Deník pak vedete v listinné formě. Pokud oprávněné osoby nemají podpisové certifikáty, může to být výhodný postup. Jak Denní protokol vytisknout, popisuje <a href="/buildary-help-preview/diary/download">Tisk a export deníku</a>.</p><p>Elektronický podpis si přitom můžete kdykoli zřídit – možnosti popisují <a href="/buildary-help-preview/diary/signaturesetting">Způsoby podpisu</a>.</p>',11)])])}const g=t(d,[["render",u]]);export{b as __pageData,g as default};
